solution.solution.py:
def second_largest(xs):
    distinct = sorted(set(xs))
    return distinct[-2] if len(distinct) >= 2 else None


def without(xs, value):
    result = []
    for x in xs:
        if x != value:
            result.append(x)
    return result


def rotate(xs, k):
    if not xs:
        return []
    k %= len(xs)
    return xs[-k:] + xs[:-k] if k else xs[:]
